-- فيزياء 1: تعديل المقال 2 لهدف زاوية النظر (P1-C1-L2-O18) ليتبع الكتاب. آمن للتكرار.
begin;
update public.questions set stem = 'لماذا يؤثر اختلاف زاوية النظر في القياسات التي تجريها؟ وكيف تتجنب هذا الأثر عند قراءة التدريج؟' where id = (select q.id from public.questions q join public.objectives o on o.id=q.objective_id where o.code='P1-C1-L2-O18' and q.type='essay' and q.number=2);
update public.question_answers set model_answer = 'لأن قراءة التدريج بشكل مائل تُظهر المؤشر مقابلًا لتدريج غير التدريج الذي يقابله فعلًا، فنحصل على قيمة مختلفة عن القيمة الصحيحة وغير مضبوطة؛ وهو خطأ شخصي من القارئ لا من الأداة. ولتجنبه تُقرأ التدريجات بالنظر عموديًّا عليها وبعين واحدة، بحيث تكون العين مقابلة للمؤشر مباشرة، فتكون القراءة أضبط.', answer_elements = '["القراءة المائلة تعطي قيمة مختلفة عن الصحيحة (غير مضبوطة)", "السبب: المؤشر يبدو مقابلًا لتدريج آخر عند النظر بزاوية", "الخطأ شخصي من القارئ لا من الأداة", "التجنب: النظر عموديًّا على التدريج وبعين واحدة"]'::jsonb,
  marks = '[{"element": "بيان أن القراءة المائلة تعطي قيمة مختلفة عن الصحيحة", "marks": 1}, {"element": "تفسير السبب (المؤشر يبدو مقابلًا لتدريج آخر)", "marks": 1}, {"element": "أنه خطأ شخصي من القارئ", "marks": 1}, {"element": "طريقة التجنب: النظر عموديًّا وبعين واحدة", "marks": 1}]'::jsonb, rubric = '[{"level": "4 درجات", "description": "يبين أثر زاوية النظر في القراءة ويفسر سببه ويذكر أنه خطأ شخصي ويصف طريقة التجنب"}, {"level": "2–3 درجات", "description": "يبين الأثر ويذكر طريقة التجنب مع نقص في التفسير"}, {"level": "1 درجة", "description": "يذكر طريقة التجنب أو الأثر فقط"}, {"level": "صفر", "description": "إجابة خاطئة أو لا إجابة"}]'::jsonb, common_errors = '["الظن أن زاوية النظر تغيّر قيمة أصغر تدريج في الأداة", "الاكتفاء بقول «القراءة خاطئة» دون تفسير السبب أو طريقة التجنب", "ملاحظة للمصحح: يُقبل وصف الأثر بلفظ «الدقة» كما ورد في سؤال الكتاب ص21، ما دام الطالب يبيّن أن القراءة المائلة تعطي قيمة مختلفة عن الصحيحة"]'::jsonb where question_id = (select q.id from public.questions q join public.objectives o on o.id=q.objective_id where o.code='P1-C1-L2-O18' and q.type='essay' and q.number=2);
commit;
select q.stem from public.questions q where q.id = (select q.id from public.questions q join public.objectives o on o.id=q.objective_id where o.code='P1-C1-L2-O18' and q.type='essay' and q.number=2);
